import React, { createContext, useContext, useEffect, useLayoutEffect, useMemo, useState } from 'react';
import { useTheme } from 'next-themes';
import { useCarWash } from '../store';
import { useFeatures } from './features';
import { settingsApi } from '../api';

/**
 * Tailwind's red scale, in OKLCH, as the shape every generated scale copies.
 *
 * Only the hue is taken from the carwash's chosen colour. Lightness is kept from
 * this reference so that brand-50 stays a pale wash and brand-900 stays dark
 * enough to read white text on, whatever colour is picked — a scale generated by
 * simply tinting the raw hex would put white text on yellow and call it a theme.
 */
const RAMP: Array<[step: number, lightness: number, chroma: number]> = [
  [50, 97.1, 0.013], [100, 93.6, 0.032], [200, 88.5, 0.062], [300, 80.8, 0.114],
  [400, 70.4, 0.191], [500, 63.7, 0.237], [600, 57.7, 0.245], [700, 50.5, 0.213],
  [800, 44.4, 0.177], [900, 39.6, 0.141], [950, 25.8, 0.092],
];

/** Chroma of the reference red at step 500, measured with the converter below. */
const REFERENCE_CHROMA = 0.208;

const srgbToLinear = (c: number) => (c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4));

/** sRGB hex to OKLCH. Returns null for anything that is not a #rgb or #rrggbb colour. */
export const hexToOklch = (hex: string): { l: number; c: number; h: number } | null => {
  const raw = hex.trim().replace(/^#/, '');
  if (!/^[0-9a-fA-F]{3}$|^[0-9a-fA-F]{6}$/.test(raw)) return null;
  const full = raw.length === 3 ? raw.split('').map(ch => ch + ch).join('') : raw;

  const r = srgbToLinear(parseInt(full.slice(0, 2), 16) / 255);
  const g = srgbToLinear(parseInt(full.slice(2, 4), 16) / 255);
  const b = srgbToLinear(parseInt(full.slice(4, 6), 16) / 255);

  const l_ = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m_ = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s_ = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);

  const L = 0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_;
  const A = 1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_;
  const B = 0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_;

  let h = (Math.atan2(B, A) * 180) / Math.PI;
  if (h < 0) h += 360;
  return { l: L, c: Math.sqrt(A * A + B * B), h };
};

const VARIABLES = RAMP.map(([step]) => `--color-brand-${step}`);

/**
 * Repaints the whole panel by rewriting eleven CSS variables.
 *
 * Every brand-coloured utility in the app resolves through these, so this is the
 * only place that needs to know a tenant can choose a colour. Passing null puts
 * the stylesheet's own values back.
 */
export const applyBrandColor = (hex: string | null | undefined) => {
  const root = document.documentElement;
  const parsed = hex ? hexToOklch(hex) : null;

  if (!parsed) {
    VARIABLES.forEach(v => root.style.removeProperty(v));
    return;
  }

  // A deliberately muted brand should stay muted, so the reference chroma is
  // scaled towards whatever was picked rather than replaced by it. The clamp
  // keeps a near-grey choice from producing a scale with no colour at all.
  const saturation = Math.min(1.2, Math.max(0.4, parsed.c / REFERENCE_CHROMA));

  RAMP.forEach(([step, lightness, chroma]) => {
    root.style.setProperty(
      `--color-brand-${step}`,
      `oklch(${lightness}% ${(chroma * saturation).toFixed(4)} ${parsed.h.toFixed(3)})`,
    );
  });
};

/**
 * Last known branding per carwash, so a reload paints in their colour straight away.
 *
 * Without this the panel renders red, waits for /settings, then repaints — a visible flash
 * of the wrong brand on every single page load. The cache is only ever a head start: the
 * response still overwrites it, so a colour changed on another device corrects itself as
 * soon as the request lands.
 */
const cacheKey = (tenantId: string) => `sw:branding:${tenantId}`;

const readCache = (tenantId: string): Partial<Branding> | null => {
  try {
    const raw = localStorage.getItem(cacheKey(tenantId));
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
};

const writeCache = (tenantId: string, value: Omit<Branding, 'refresh' | 'loaded'>) => {
  try { localStorage.setItem(cacheKey(tenantId), JSON.stringify(value)); } catch { /* private mode */ }
};

type Branding = {
  /** The carwash's own logo, or null to fall back to the SmartWash mark. */
  logoUrl: string | null;
  primaryColor: string | null;
  tagline: string | null;
  loaded: boolean;
  /** Re-reads the settings, so saving new branding takes effect without a reload. */
  refresh: () => void;
};

const BrandingContext = createContext<Branding>({
  logoUrl: null, primaryColor: null, tagline: null, loaded: false, refresh: () => { },
});

export const useBranding = () => useContext(BrandingContext);

/**
 * Loads the carwash's branding once per sign-in and puts it to work: the colour
 * on the stylesheet, the logo in this context for <Logo brand="tenant" />, and
 * the light/dark preference through next-themes.
 *
 * Branding is a paid feature, so a carwash on the starter plan keeps the
 * SmartWash red and mark even if values were stored while it was on a higher
 * plan. The settings screen already hides the tab the same way; this makes the
 * gate real rather than cosmetic.
 */
export const BrandingProvider = ({ children }: { children: React.ReactNode }) => {
  const { user } = useCarWash();
  const { setTheme } = useTheme();
  const { has, loading: featuresLoading } = useFeatures();
  const [branding, setBranding] = useState<Omit<Branding, 'refresh'>>({
    logoUrl: null, primaryColor: null, tagline: null, loaded: false,
  });
  const [reloadToken, setReloadToken] = useState(0);

  const allowed = has('branding');

  // Before paint, not after: the point is that the first frame is already the right colour.
  useLayoutEffect(() => {
    if (!user?.tenantId) return;
    const cached = readCache(user.tenantId);
    if (!cached) return;
    applyBrandColor(cached.primaryColor ?? null);
    setBranding(b => (b.loaded ? b : {
      logoUrl: cached.logoUrl ?? null,
      primaryColor: cached.primaryColor ?? null,
      tagline: cached.tagline ?? null,
      loaded: false,
    }));
  }, [user?.tenantId]);

  useEffect(() => {
    if (!user || featuresLoading) return;
    let alive = true;

    settingsApi.get()
      .then(s => {
        if (!alive) return;
        setTheme(s.theme === 'dark' || s.theme === 'light' ? s.theme : 'system');

        const logoUrl = allowed ? (s.logoUrl?.trim() || null) : null;
        const primaryColor = allowed ? (s.primaryColor?.trim() || null) : null;
        const tagline = s.tagline?.trim() || null;
        applyBrandColor(primaryColor);
        setBranding({ logoUrl, primaryColor, tagline, loaded: true });
        if (user.tenantId) writeCache(user.tenantId, { logoUrl, primaryColor, tagline });
      })
      .catch(() => { if (alive) setBranding(b => ({ ...b, loaded: true })); });

    return () => { alive = false; };
  }, [user?.tenantId, allowed, featuresLoading, reloadToken]);

  // Signing out has to take the colour with it, or the next carwash to sign in
  // on this browser sees the previous one's palette until its settings arrive.
  useEffect(() => {
    if (user) return;
    applyBrandColor(null);
    setBranding({ logoUrl: null, primaryColor: null, tagline: null, loaded: false });
  }, [user]);

  const value = useMemo(
    () => ({ ...branding, refresh: () => setReloadToken(n => n + 1) }),
    [branding],
  );
  return <BrandingContext.Provider value={value}>{children}</BrandingContext.Provider>;
};
